"""Blocco della pagina «Fonti e suggerimenti»: la riga della fonte nel riquadro Trama (voce 20).
Scritto a mano nel canvas: `python add_fonte_riga.py` lo inserisce in canvas/Fonti e suggerimenti.dc.html (una volta sola).
Non dipende da lib2 (nessun setup). Una rigenerazione di p_fonti.py lo cancella."""
import html as _h, json
def tag(t,k=''): return f'<span class="dc-chip {k}">{t}</span>'
def ul(items): return '<ul class="dc-ul">'+''.join(f'<li>{i}</li>' for i in items)+'</ul>'
def tbl(head,rows):
    h=''.join(f'<th>{x}</th>' for x in head); r=''.join('<tr>'+''.join(f'<td>{c}</td>' for c in row)+'</tr>' for row in rows)
    return f'<div class="dc-scroll"><table class="dc-tbl"><thead><tr>{h}</tr></thead><tbody>{r}</tbody></table></div>'
def sec(title,sub,body=''): return f'<div class="dc-sec"><h2 class="dc-h2">{title}</h2>'+(f'<p class="dc-sub">{sub}</p>' if sub else '')+body+'</div>'
PARAS=['Tony Stark, miliardario e inventore, viene rapito durante una dimostrazione di armi in Afghanistan.','Nella grotta in cui è prigioniero costruisce la prima armatura e fugge, deciso a cambiare il proprio destino.','Tornato a casa, annuncia che la sua azienda non costruirà più armi e lavora a una versione perfezionata dell\'armatura.','Intanto un socio di lunga data prepara in segreto un\'armatura più grande, per riprendersi l\'azienda.','Lo scontro finale avviene sul tetto della sede, mentre la città guarda.','Nel frattempo i suoi alleati scoprono che il progetto è stato venduto a una società ombra, e devono decidere se fidarsi di lui.','Alla fine tutti si ritrovano sul tetto, e nessuno è più quello di prima.','Il giorno dopo la città si sveglia con una nuova skyline e con molte domande rimaste senza risposta.','Stark riceve una visita inattesa da un uomo che dice di conoscere il vero scopo del progetto.','La conversazione si chiude con una promessa e con una porta lasciata appena socchiusa.']
SRC={'it':('Fonte:','Wikipedia','licenza CC BY-SA 4.0')}
V='''html{overflow:hidden}body{margin:0;padding:16px;background:var(--panel)}
.spoiler-box--plot{height:460px}
.v-corr .plot__source,.v-fade .plot__source,.v-pad .plot__source{position:sticky;bottom:0;margin:var(--sp-3) 0 0;padding-top:var(--sp-2);background:var(--panel-2);font-size:var(--fs-caption);color:var(--muted-on-dark)}
.v-fade .plot__source{padding-top:var(--sp-3)}
.v-fade .plot__source::before{content:"";position:absolute;inset-inline:0;bottom:100%;height:var(--sp-6);background:linear-gradient(to top,var(--panel-2),transparent);pointer-events:none}
.v-pad .plot__source{padding-top:var(--sp-4)}
.v-foot .spoiler-box__foot{font-size:var(--fs-caption);color:var(--muted-on-dark)}
.plot__source a,.spoiler-box__foot a{color:var(--highlight)}'''
def frame(label,v,theme,w,scroll,hidden=False,lang_src=None):
    text=''.join(f'<p>{p}</p>' for p in PARAS)
    s=lang_src or 'Fonte: <a href="#">Wikipedia</a>, <a href="#">licenza CC BY-SA 4.0</a>'
    body=f'<div class="plot">{text}</div><p class="plot__source">{s}</p>' if v!='foot' else f'<div class="plot">{text}</div>'
    foot=f'<p class="spoiler-box__foot">{s}</p>' if v=='foot' else ''
    hid=' data-hidden="true" aria-hidden="true"' if hidden else ''
    eye='<button type="button" class="spoiler-box__eye" aria-expanded="%s" aria-label="%s"><svg class="lucide" xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2.062 12.348a1 1 0 0 1 0-.696 10.75 10.75 0 0 1 19.876 0 1 1 0 0 1 0 .696 10.75 10.75 0 0 1-19.876 0"/><circle cx="12" cy="12" r="3"/></svg></button>'%('false' if hidden else 'true','Mostra la trama' if hidden else 'Nascondi la trama')
    art=f'<article class="spoiler-box spoiler-box--plot v-{v}" style="width:{w}px"><div class="spoiler-box__head"><h3 class="section-title">Trama</h3>{eye}</div><div class="spoiler-box__content" role="region"{hid}>{body}</div>{foot}</article>'
    doc=(f'<!doctype html><html lang="it" data-theme="{theme}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="tokens.css"><link rel="stylesheet" href="app.css">'
         f'<link href="https://fonts.googleapis.com/css2?family=Anton&family=Hanken+Grotesk:wght@400;500;600;700;800&display=swap" rel="stylesheet"><style>{V}</style></head><body>{art}'
         f'<script>var c=document.querySelector(".spoiler-box__content");c.scrollTop={scroll};</script></body></html>')
    return (f'<div class="dc-fw"><div class="dc-fl">{label}</div><iframe title="{label}" srcdoc="{_h.escape(doc.replace("viewBox","viewbox"),quote=True)}" '
            f'style="width:{w+32}px;height:500px;border:0;border-radius:var(--r-md);display:block;max-width:100%"></iframe></div>')
def row(*f): return '<div class="dc-row">'+''.join(f)+'</div>'
MID=100
def build():
    chip=tag('proposta · non implementata','k2')
    why=('<b>Raccomandazione A: (1), la sfumatura.</b> Il difetto è il taglio netto: il testo che passa sotto la riga fissa si ferma a metà riga, subito sopra la fonte. Una sfumatura da <code>--panel-2</code> a trasparente alta <code>--sp-6</code> (24 px, circa una riga di testo) sopra la riga lo scioglie, senza spostare la fonte e senza toccare <code>SpoilerBox</code>. '
         'In più la riga prende più aria: <code>padding-top</code> da <code>--sp-2</code> a <code>--sp-3</code>; a fine scorrimento il testo e la fonte distano 24 px (<code>margin-top</code> <code>--sp-3</code> + <code>padding-top</code> <code>--sp-3</code>), come il padding del riquadro. '
         '<b>Perché non (2):</b> uno sfondo pieno con più spazio sopra non toglie il taglio netto, lo allontana soltanto: il margine di un elemento sticky non è dipinto, quindi il testo vi passa dentro e viene tagliato ancora; vale solo il <code>padding-top</code> (variante 2 sotto, 36 px di riga). '
         '<b>Perché non (3):</b> già scartata: senza scorrere la fonte non si vede. <b>Alternativa (4):</b> la riga fuori dall\'area che scorre (nuova uscita <code>footer</code> in <code>SpoilerBox</code>): niente sfumatura e fonte nitida anche con la trama sfocata, ma l\'area di testo perde 35 px (352 → 317) e si tocca un componente condiviso.')
    A=[frame('Oggi · inizio','corr','light',550,0),frame('Oggi · metà','corr','light',550,MID),frame('Oggi · fine','corr','light',550,99999)]
    B=[frame('Proposta (1) · inizio','fade','light',550,0),frame('Proposta (1) · metà','fade','light',550,MID),frame('Proposta (1) · fine','fade','light',550,99999)]
    C=[frame('Proposta (1) · metà · scuro','fade','dark',550,MID),frame('Proposta (1) · sfocata · chiaro','fade','light',550,0,hidden=True),frame('Proposta (1) · sfocata · scuro','fade','dark',550,0,hidden=True)]
    D=[frame('Telefono 390 px · riquadro 334 px · metà · chiaro','fade','light',334,MID),frame('Telefono · metà · scuro','fade','dark',334,MID),frame('Telefono stretto · riquadro 280 px · la fonte va a capo (51 px)','fade','dark',280,MID)]
    E=[frame('Variante (2) · solo spazio, sfondo pieno · metà','pad','light',334,MID),frame('Variante (4) · riga fuori dallo scorrimento · metà','foot','light',334,MID),frame('Variante (4) · sfocata: la fonte resta nitida','foot','light',334,0,hidden=True)]
    rows_w=[['it','285','Fonte: Wikipedia, licenza CC BY-SA 4.0'],['de','286','Quelle: Wikipedia, Lizenz CC BY-SA 4.0'],['en','293','Source: Wikipedia, CC BY-SA 4.0 license'],['es','296','Fuente: Wikipedia, licencia CC BY-SA 4.0'],['fr','<b>297</b>','Source : Wikipédia, licence CC BY-SA 4.0']]
    return (f'<div class="dc-sec"><h2 class="dc-h2">Decisione · la riga della fonte nel riquadro Trama: sfumatura, respiro, fine dello scorrimento</h2><div>{chip}</div>'
      '<p class="dc-sub">Riferimento: main e0db763 più la correzione non ancora su main (riga fuori da <code>.plot</code>, <code>margin: var(--sp-3) 0 0</code>, <code>padding-top: var(--sp-2)</code>), che qui è “Oggi”. Misurato nel browser con il CSS del canvas e i font veri (Anton, Hanken Grotesk); riquadro alto 460 px (<code>.spoiler-box--plot</code>, TitleDetailsPanel.less r.328), testo di prova più lungo della trama vera di un film. Le larghezze 550 / 334 / 280 sono larghezze di <b>prova</b> del riquadro: la larghezza vera nella pagina intera non l\'ho misurata (assunto: finestra − 56 px su telefono).</p>'
      f'<div class="dc-box"><div class="dc-fl">Scelta · variante preferita e perché</div><p>{why}</p></div>'
      +sec('A · Come si stacca il testo dalla riga','Stessa riga, scorrimento a inizio, a metà e a fine. A metà, in “Oggi” la riga di testo «Lo scontro finale…» è tagliata di netto sopra la fonte; nella proposta sfuma.','<div style="display:flex;flex-direction:column;gap:var(--sp-5)">'+row(*A)+row(*B)+'</div>')
      +sec('Chiaro e scuro, e con la trama sfocata','La riga sta dentro l\'area che scorre (<code>inert</code> e <code>aria-hidden</code> finché la trama è nascosta): si sfoca insieme al testo. È la risposta a D.','<div style="display:flex;flex-direction:column;gap:var(--sp-5)">'+row(*C)+'</div>')
      +sec('C · Telefono: una riga o due','La fonte sta su una riga da un riquadro di 297 px in su (la più lunga è la francese); sotto va a capo, senza puntini. Altezza della riga con la proposta (<code>padding-top: var(--sp-3)</code>): una riga 32 px, due righe 51 px. La riga «Fonte: TMDB» (serie) è sempre su una riga.',
        '<div style="display:flex;flex-direction:column;gap:var(--sp-5)">'+row(*D)+'</div>'+tbl(['Lingua','Riquadro minimo per una riga (px)','Testo'],rows_w)+'<p class="dc-sub">Con 390 px di finestra il riquadro vale circa 334 px (non verificato nella pagina vera): una riga in tutte le lingue; con 360 px circa 304: ancora una riga; con 320 px circa 264: due righe.</p>')
      +sec('B · Fine dello scorrimento','Nessun padding in più sotto il testo: la riga è dopo il testo nel flusso, quindi a fine scorrimento non può coprire l\'ultima riga. Misurato (testo italiano): distanza tra l\'ultima riga e la fonte 24 px (12 di margine + 12 di padding), fonte a 24 px dal bordo del riquadro (uguale al padding laterale, <code>--sp-6</code>); nessuna sovrapposizione. Durante lo scorrimento l\'area di testo visibile è 352 − 32 = 320 px.',
        tbl(['Stato','Ultima riga → testo della fonte','Testo della fonte → bordo del riquadro','Si sovrappongono?'],[['Oggi (con la correzione)','20 px (12 + 8)','24 px','no'],['Proposta (1)','24 px (12 + 12)','24 px','no'],['Variante (2)','28 px (12 + 16)','24 px','no'],['Variante (4)','16 px (gap del riquadro)','24 px','no']]))
      +sec('Le due alternative, per confronto','Telefono, riquadro 334 px, chiaro. (2): lo sfondo pieno stacca la riga ma il taglio resta. (4): la riga è fuori dall\'area che scorre e resta nitida anche con la trama sfocata.','<div style="display:flex;flex-direction:column;gap:var(--sp-5)">'+row(*E)+'</div>')
      +sec('D · La riga sfocata insieme al testo','<b>Resta sfocata.</b> È l\'attribuzione di un testo che, finché non si preme l\'occhio, non si legge: sfocarla è coerente e già così nel codice (<code>inert</code> + <code>aria-hidden</code> sul contenitore, quindi anche i link non prendono il focus). Lasciarla nitida richiede la variante (4); se il committente la vuole nitida, è la ragione per scegliere (4).')
      +sec('Regola per Code','Stato di partenza: la correzione già applicata (riga fuori da <code>.plot</code>, ancora dentro <code>SpoilerBox</code>). Solo token esistenti.',
        '<pre><code>// PlotSection.tsx: PlotSource è figlio di SpoilerBox, accanto a .plot (non dentro)\n&lt;&gt;\n  &lt;div className="plot"&gt;…&lt;/div&gt;\n  &lt;PlotSource plot={…} /&gt;\n&lt;/&gt;\n\n// PlotSection.less\n.plot__source {\n  position: sticky;\n  bottom: 0;\n  margin: var(--sp-3) 0 0;\n  padding-top: var(--sp-3);            // era --sp-2\n  background: var(--panel-2);\n  font-size: var(--fs-caption);\n  color: var(--muted-on-dark);\n\n  a { color: var(--highlight); }       // .plot a non lo raggiunge più\n\n  // sfumatura: il testo non è tagliato di netto sopra la riga\n  &::before {\n    content: "";\n    position: absolute;\n    inset-inline: 0;\n    bottom: 100%;\n    height: var(--sp-6);\n    background: linear-gradient(to top, var(--panel-2), transparent);\n    pointer-events: none;\n  }\n}</code></pre>'
        +ul(['Nessun valore nuovo: <code>--sp-3</code>, <code>--sp-6</code>, <code>--panel-2</code>, <code>--fs-caption</code>, <code>--muted-on-dark</code>, <code>--highlight</code>.','Nessun padding in fondo a <code>.plot</code>: la riga è nel flusso dopo il testo.','Telefono: nessuna regola; la fonte va a capo da sé sotto i 297 px di riquadro (51 px di altezza).','Non toccati <code>SpoilerBox</code> né <code>TitleDetailsPanel.less</code>.','Non verificato: Safari e Firefox (gradiente verso <code>transparent</code>); la larghezza vera del riquadro su telefono.','Deviazioni di DESIGN.md: «Riga della fonte della trama (<code>.plot__source</code>): <code>padding-top</code> <code>--sp-3</code> (era <code>--sp-2</code>) e sfumatura da <code>--panel-2</code> a trasparente alta <code>--sp-6</code> sopra la riga, perché il testo non sia tagliato di netto sotto la riga fissa.»']))
      +sec('Prima, dopo, file','',tbl(['Cosa','Prima','Dopo','File'],[['Taglio del testo sopra la fonte','netto, a metà riga','sfumatura <code>--sp-6</code> da <code>--panel-2</code> a trasparente','PlotSection.less'],['Aria sopra la fonte','<code>padding-top: var(--sp-2)</code>','<code>var(--sp-3)</code>; 24 px dall\'ultima riga a fine scorrimento','PlotSection.less'],['Collegamenti della fonte','<code>.plot a</code> (dentro <code>.plot</code>)','<code>.plot__source a</code> (la riga è fuori da <code>.plot</code>)','PlotSection.less'],['Posizione di <code>PlotSource</code>','dentro <code>.plot</code>','accanto a <code>.plot</code>, dentro <code>SpoilerBox</code>','PlotSection.tsx']]))
      +'</div>')
if __name__=='__main__':
    p='../../canvas/Fonti e suggerimenti.dc.html'
    t=open(p,encoding='utf-8',newline='').read()
    if 'la riga della fonte nel riquadro Trama' in t: raise SystemExit('già inserito')
    end='\n</div>\n</x-dc>'
    assert t.count(end)==1, t.count(end)
    open(p,'w',encoding='utf-8',newline='').write(t.replace(end,'\n'+build()+end,1)); print('ok')
